solution.solution.cpp:
#include <algorithm>
#include <map>
#include <string>
#include <vector>

struct Sample { std::string name; long long micros; };
struct Row { std::string name; int count; long long total; long long worst; double average; };

std::vector<Row> summarise(const std::vector<Sample>& samples)
{
    std::map<std::string, Row> byName;
    for (const Sample& s : samples)
    {
        Row& r{ byName.try_emplace(s.name, Row{ s.name, 0, 0, 0, 0.0 }).first->second };
        ++r.count;
        r.total += s.micros;
        r.worst = std::max(r.worst, s.micros);
    }
    std::vector<Row> rows;
    for (auto& [name, r] : byName)
    {
        r.average = static_cast<double>(r.total) / r.count;
        rows.push_back(r);
    }
    std::sort(rows.begin(), rows.end(), [](const Row& a, const Row& b) {
        return a.total != b.total ? a.total > b.total : a.name < b.name;
    });
    return rows;
}

unitTests:
TEST("the example")
{
    const auto rows{ summarise({ { "render", 9000 }, { "physics", 3000 }, { "render", 11000 }, { "ai", 2000 } }) };
    CHECK_EQ(rows.size(), std::size_t{ 3 });
    CHECK_EQ(rows[0].name, std::string("render"));
    CHECK_EQ(rows[0].count, 2);
    CHECK_EQ(rows[0].total, 20000LL);
    CHECK_EQ(rows[0].worst, 11000LL);
    CHECK_NEAR(rows[0].average, 10000.0, 1e-9);
    CHECK_EQ(rows[2].name, std::string("ai"));
}
TEST("ties sorted by name") { const auto rows{ summarise({ { "b", 5 }, { "a", 5 } }) }; CHECK_EQ(rows[0].name, std::string("a")); CHECK_EQ(rows[1].name, std::string("b")); }
TEST("averages are not rounded") { const auto rows{ summarise({ { "x", 1 }, { "x", 2 } }) }; CHECK_NEAR(rows[0].average, 1.5, 1e-9); }
TEST("worst case") { const auto rows{ summarise({ { "io", 100 }, { "io", 4000 }, { "io", 50 } }) }; CHECK_EQ(rows[0].worst, 4000LL); CHECK_EQ(rows[0].count, 3); }
TEST("no samples") { CHECK(summarise({}).empty()); }

